theorem homogeneous3_pos_of_ne_zero {x y z : ℝ}
    (hx : 0 ≤ x) (hy : 0 ≤ y) (hz : 0 ≤ z) (hne : x ≠ 0 ∨ y ≠ 0 ∨ z ≠ 0) (n : ℕ) :
    0 < homogeneous3 x y z n

theorem coefficientDifference_pos_of_le {x y z : ℝ}
    (hx : 0 ≤ x) (hy : 0 ≤ y) (hz : 0 ≤ z) {N : ℕ}
    (hpos : 0 < coefficientDifference x y z N) {j : ℕ} (hj : j ≤ N) :
    0 < coefficientDifference x y z j

theorem coefficientDifference_prev_pos {x y z : ℝ}
    (hx : 0 ≤ x) (hy : 0 ≤ y) (hz : 0 ≤ z) {n : ℕ}
    (hpos : 0 < coefficientDifference x y z (n + 1)) :
    0 < coefficientDifference x y z n

theorem coefficientDifference_zero_last_le_one {x y : ℝ}
    (hx : 0 ≤ x) (hx1 : x ≤ 1) (hy : 0 ≤ y) (hy1 : y ≤ 1) (n : ℕ) :
    coefficientDifference x y 0 n ≤ 1

theorem comparisonAuxCoefficient_prev_pos {α β x y z : ℝ}
    (hβx : x < β) (hxy : y < x) (hyz : z < y) (hz : 0 < z) {n : ℕ}
    (hB0 : 0 < weightedCoefficient β x y z n)
    (hB1 : 0 < weightedCoefficient β x y z (n + 1))
    (ha : 0 ≤ comparisonAuxCoefficient α β x y z (n + 2)) :
    0 < comparisonAuxCoefficient α β x y z (n + 1)

theorem weightedCoefficient_pos_of_le {β x y z : ℝ}
    (hx : 0 < x) (hy : 0 < y) (hz : 0 < z) {N : ℕ}
    (hpos : 0 < weightedCoefficient β x y z N) {j : ℕ} (hj : j ≤ N) :
    0 < weightedCoefficient β x y z j

theorem weightedCoefficient_prev_pos {β x y z : ℝ}
    (hx : 0 < x) (hy : 0 < y) (hz : 0 < z) {n : ℕ}
    (hpos : 0 < weightedCoefficient β x y z (n + 1)) :
    0 < weightedCoefficient β x y z n

theorem coefficientDifference_sigma_lt_two {x y z : ℝ} {N : ℕ}
    (hx : 0 ≤ x) (hy : 0 ≤ y) (hz : 0 ≤ z) (hN : 1 ≤ N)
    (hpos : 0 < coefficientDifference x y z N) : 3 - x - y - z < 2

theorem abs_pow_sub_pow_le_on_unit (t : ℕ) {x y : ℝ}
    (hx : x ∈ Set.Icc 0 1) (hy : y ∈ Set.Icc 0 1) :
    |x ^ t - y ^ t| ≤ t * |x - y|

theorem missingMassTerm_lipschitz (t : ℕ) {x y : ℝ}
    (hx : x ∈ Set.Icc 0 1) (hy : y ∈ Set.Icc 0 1) :
    |missingMassTerm t x - missingMassTerm t y| ≤ (t + 1) * |x - y|

theorem sorted_tail_le (p : ProbabilityVector ℕ) (hp : Antitone p.coord) {h : ℝ}
    (hh : 0 ≤ h) (hbudget : p.entropy ≤ ENNReal.ofReal h) (N : ℕ) (hN : 1 ≤ N) :
    (∑' i : {n : ℕ // N ≤ n}, p.coord i) ≤ h / Real.log ((N : ℝ) + 1)

theorem tsum_entropy_le_of_feasible {ι : Type*} (p : ProbabilityVector ι) {h : ℝ}
    (hh : 0 ≤ h) (hp : p.entropy ≤ ENNReal.ofReal h) :
    (∑' i, Real.negMulLog (p.coord i)) ≤ h

theorem rolle_multiplicity {f : ℝ → ℝ} {n : ℕ}
    (hf : ∀ x, AnalyticAt ℝ f x) (hd : ZeroMultiplicityBound (deriv f) n) :
    ZeroMultiplicityBound f (n + 1)

theorem zeroMultiplicityBound_one_of_deriv_pos {f : ℝ → ℝ}
    (hf : ∀ x, AnalyticAt ℝ f x) (hd : ∀ x, 0 < deriv f x) :
    ZeroMultiplicityBound f 1

theorem ZeroMultiplicityBound.card_le {f : ℝ → ℝ} {n : ℕ}
    (hb : ZeroMultiplicityBound f n) (hf : ∀ x, AnalyticAt ℝ f x)
    (s : Finset ℝ) (hs : ∀ x ∈ s, f x = 0) : s.card ≤ n

theorem ZeroMultiplicityBound.sum_le {f : ℝ → ℝ} {n : ℕ}
    (hb : ZeroMultiplicityBound f n) (s : Finset ℝ) (hs : ∀ x ∈ s, f x = 0) :
    (∑ x ∈ s, analyticOrderAt f x) ≤ (n : ℕ∞)

theorem deriv_neg_of_simple_zero_negative_right {f : ℝ → ℝ} {a b : ℝ}
    (hf : AnalyticAt ℝ f a) (ho : analyticOrderAt f a = 1) (hab : a < b)
    (hn : ∀ x ∈ Ioo a b, f x < 0) : deriv f a < 0

theorem negative_on_interval_of_no_zeros {f : ℝ → ℝ} {I : Set ℝ}
    (hc : Continuous f) (hI : OrdConnected I) (hn : ∀ x ∈ I, f x ≠ 0)
    {a : ℝ} (ha : a ∈ I) (hfa : f a < 0) : ∀ x ∈ I, f x < 0

theorem exists_negative_integer_of_zero_series {f : ℝ → ℝ}
    (hs : HasSum (fun n : ℕ => f (n + 1) / (n + 1)) 0)
    (hp : ∀ᶠ x in atTop, 0 < f x) : ∃ n : ℕ, f (n + 1) < 0

theorem comparison_constant_le_entropy_recip {S m : ℝ}
    (hS : 0 < S) (hS1 : S ≤ 1) (hm : 0 ≤ m) :
    max (1 / (1 + m)) (1 / (S + 3 * m)) ≤ 1 / (S + m)

theorem hasSum_finite_replacement (s : Finset ι) (f g : ι → ℝ) {a : ℝ}
    (hf : HasSum f a) :
    HasSum (fun i => if i ∈ s then g i else f i) (a + ∑ i ∈ s, (g i - f i))

theorem homogeneous3_ratio_antitone {x y z : ℝ}
    (hx : 0 ≤ x) (hy : 0 ≤ y) (hz : 0 ≤ z) (hne : x ≠ 0 ∨ y ≠ 0 ∨ z ≠ 0) :
    Antitone (fun n => homogeneous3 x y z (n + 1) / homogeneous3 x y z n)

theorem homogeneous3_ratio_strictAnti {x y z : ℝ}
    (hx : 0 < x) (hy : 0 < y) (hz : 0 < z) :
    StrictAnti (fun n => homogeneous3 x y z (n + 1) / homogeneous3 x y z n)

theorem homogeneous3_turan_nonneg {x y z : ℝ}
    (hx : 0 ≤ x) (hy : 0 ≤ y) (hz : 0 ≤ z) (n : ℕ) :
    0 ≤ homogeneous3 x y z n ^ 2 - previousHomogeneous3 x y z n * homogeneous3 x y z (n + 1)

theorem repeatedPairValues_nonneg (p : ProbabilityVector ι) {i j : ι} {ε : ℝ}
    (hε : |ε| ≤ p.coord i) (k : ι) (_hk : k ∈ ({i, j} : Finset ι)) :
    0 ≤ repeatedPairValues p i ε k

theorem weighted_second_derivative_integral {f : ℝ → ℝ} {x y : ℝ}
    (hf : ContDiffOn ℝ 2 f (Ioo 0 1)) (hx : 0 < x) (hxy : x < y) (hy : y < 1) :
    (∫ u in x..y, (u * deriv (deriv f) u)/u) = deriv f y - deriv f x

theorem exists_hasCoeffDerivAt_homogeneousSeries (q : ℝ → (Fin 3 → ℝ)) {a : ℝ}
    (hq : DifferentiableAt ℝ q a) :
    ∃ D, HasCoeffDerivAt (fun r => homogeneousSeries (q r 0) (q r 1) (q r 2)) D a

theorem tendsto_one_of_scalarGap {α : Type*} {l : Filter α} {v : α → ℝ}
    (hv : ∀ᶠ a in l, 0 < v a) (hg : Tendsto (fun a => scalarGap (v a)) l (𝓝 0)) :
    Tendsto v l (𝓝 1)
